# ============================================================
# AEGIS NIDS - Phase 39.2 Patch (Fix RAG E2E verdict)
# ============================================================
$ErrorActionPreference = 'Stop'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS Phase 39.2 - Fix RAG E2E verdict mismatch"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"

function Deploy-File {
    param([string]$RelativePath, [string]$Base64Content, [int]$ExpectedLines)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $BackupPath = "$FullPath.phase39_2_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    Write-Host "  [OK] $((Get-Content $FullPath).Count) lines"
}

$B64_1 = ''
Deploy-File -RelativePath "core/sprint2_e2e_test.zig" -ExpectedLines 363 -Base64Content $B64_1


Write-Host ""
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | ForEach-Object { Write-Host $_ }
if ($LASTEXITCODE -eq 0) {
    Write-Host "[BUILD] SUCCESS"
} else {
    Write-Host "[BUILD] FAILED"
    exit 1
}

Write-Host ""
Write-Host "[INFO] Run: zig build test"
Write-Host "[INFO] Expected: 194 tests passed"
Write-Host ""
Write-Host "Summary of changes:"
Write-Host "  Phase 39.2 Patch (Fix RAG E2E test verdict mismatch):"
Write-Host "    FIX: sprint2_e2e_test.zig:118: Changed verdict from match_alert to match_block"
Write-Host "         Policy IR rule "BlockAPT" requires verdict=match_block (not match_alert)"
Write-Host "         severity=2 matched min_severity=2, but verdict didn't match → no rule applied → default allow"
Write-Host "    Effect: zig build test should pass 194/194"

Write-Host ""
Write-Host "Suggested git commands:"
Write-Host "  git add -A"
Write-Host "  git commit -m `"fix: phase 39.2 - RAG E2E test verdict match_alert to match_block`""
Write-Host "  git push"
